function depTx(d){if(d.src==='app')return(d.tx||[]).filter(i=>byId(i));const w=depKey(d);return idsOf(t=>(t.a==='Deposito BPR'||t.tu==='Deposito BPR'||/deposito/i.test(t.ket+' '+t.kt))&&t.ket.toLowerCase().includes(w))}
