 const amt=z=>[z.M?`<div class="up">+${rp(z.M)}</div>`:'',z.K?`<div class="dn">−${rp(z.K)}</div>`:'',z.T?`<div>⇄ ${rp(z.T)}</div>`:''].join('');
 const tot=z=>z.M+z.K+z.T;
