const KOSPJ='Pinjam uang kos',kosLoan=t=>t.sb===KOSPJ&&t.kt==='Pinjam dari uang kos',kosRepay=t=>t.sb===KOSPJ&&t.kt==='Ganti uang kos';
function kosLoans(d=today){const L=S.tx.filter(t=>t.d<=d&&kosLoan(t)&&!t.lunas).sort(txCmp).map(t=>({t,sisa:t.j}));let pay=S.tx.filter(t=>t.d<=d&&kosRepay(t)).reduce((s,t)=>s+t.j,0);
 for(const l of L){const x=Math.min(l.sisa,pay);l.sisa-=x;pay-=x}return{open:L.filter(l=>l.sisa>0),total:L.filter(l=>l.sisa>0).reduce((s,l)=>s+l.sisa,0),lebih:pay}}
